{
  "name": "NutriVision Pro",
  "description": "A high-performance food nutrition analyzer using Gemini AI for object detection and detailed macro-nutritional breakdown. Track your daily targets and get smart healthy alternatives.",
  "requestFramePermissions": ["camera"]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface BoundingBox {
  ymin: number;
  xmin: number;
  ymax: number;
  xmax: number;
}

export interface NutritionData {
  calories: number;
  protein: number;
  carbs: number;
  fat: number;
  fiber: number;
}

export interface FoodItem {
  id: string;
  name: string;
  confidence: number;
  box: BoundingBox;
  nutritionPer100g: NutritionData;
  estimatedWeightGrams: number;
}

export interface UserProfile {
  name: string;
  dailyTargets: NutritionData;
}

export interface DetectionResult {
  items: FoodItem[];
  smartAlternatives: {
    name: string;
    reason: string;
    estimatedMacros: Partial<NutritionData>;
  }[];
}

export interface AppState {
  profile: UserProfile;
  history: {
    date: string;
    items: FoodItem[];
  }[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { DetectionResult } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export async function analyzeFoodImage(base64Image: string): Promise<DetectionResult> {
  const modelName = "gemini-3-flash-preview";

  const prompt = `
    Analyze this food image. 
    1. Detect all distinct food items.
    2. Provide normalized bounding boxes [ymin, xmin, ymax, xmax] (0-1000).
    3. Calculate nutritional data (Calories, Protein, Carbs, Fat, Fiber) per 100g.
    4. Estimate the weight of the portion in the image.
    5. Suggest 3 healthier or macro-balanced alternatives if the food is high in fat/sugar.
  `;

  const response = await ai.models.generateContent({
    model: modelName,
    contents: [
      {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: base64Image } },
          { text: prompt }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          items: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                name: { type: Type.STRING },
                confidence: { type: Type.NUMBER },
                box: {
                  type: Type.OBJECT,
                  properties: {
                    ymin: { type: Type.NUMBER },
                    xmin: { type: Type.NUMBER },
                    ymax: { type: Type.NUMBER },
                    xmax: { type: Type.NUMBER }
                  },
                  required: ["ymin", "xmin", "ymax", "xmax"]
                },
                nutritionPer100g: {
                  type: Type.OBJECT,
                  properties: {
                    calories: { type: Type.NUMBER },
                    protein: { type: Type.NUMBER },
                    carbs: { type: Type.NUMBER },
                    fat: { type: Type.NUMBER },
                    fiber: { type: Type.NUMBER }
                  },
                  required: ["calories", "protein", "carbs", "fat", "fiber"]
                },
                estimatedWeightGrams: { type: Type.NUMBER }
              },
              required: ["id", "name", "confidence", "box", "nutritionPer100g", "estimatedWeightGrams"]
            }
          },
          smartAlternatives: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                reason: { type: Type.STRING },
                estimatedMacros: {
                  type: Type.OBJECT,
                  properties: {
                    calories: { type: Type.NUMBER },
                    protein: { type: Type.NUMBER },
                    carbs: { type: Type.NUMBER },
                    fat: { type: Type.NUMBER }
                  }
                }
              },
              required: ["name", "reason"]
            }
          }
        },
        required: ["items", "smartAlternatives"]
      }
    }
  });

  try {
    return JSON.parse(response.text) as DetectionResult;
  } catch (error) {
    console.error("Failed to parse Gemini response:", error);
    throw new Error("Invalid response from AI analysis");
  }
}

import React from 'react';
import { FoodItem } from '../types';

interface DetectionOverlayProps {
  items: FoodItem[];
  imageWidth: number;
  imageHeight: number;
}

const DetectionOverlay: React.FC<DetectionOverlayProps> = ({ items, imageWidth, imageHeight }) => {
  return (
    <svg 
      className="absolute top-0 left-0 w-full h-full pointer-events-none"
      viewBox={`0 0 ${imageWidth} ${imageHeight}`}
    >
      {items.map((item) => {
        const x = (item.box.xmin / 1000) * imageWidth;
        const y = (item.box.ymin / 1000) * imageHeight;
        const width = ((item.box.xmax - item.box.xmin) / 1000) * imageWidth;
        const height = ((item.box.ymax - item.box.ymin) / 1000) * imageHeight;

        return (
          <g key={item.id}>
            <rect
              x={x}
              y={y}
              width={width}
              height={height}
              fill="transparent"
              stroke="#10b981"
              strokeWidth="2"
              className="transition-all duration-300"
            />
            <rect
              x={x}
              y={y - 24}
              width={width}
              height="24"
              fill="#10b981"
              opacity="0.9"
            />
            <text
              x={x + 4}
              y={y - 8}
              fill="white"
              fontSize="12"
              fontWeight="600"
            >
              {item.name} ({(item.confidence * 100).toFixed(0)}%)
            </text>
          </g>
        );
      })}
    </svg>
  );
};

export default DetectionOverlay;

import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { NutritionData } from '../types';

interface MacroTrackerProps {
  current: NutritionData;
  targets: NutritionData;
}

const MacroTracker: React.FC<MacroTrackerProps> = ({ current, targets }) => {
  const getProgressColor = (val: number, target: number) => {
    const ratio = val / target;
    if (ratio > 1.1) return '#ef4444'; // Over limit - Red
    if (ratio > 0.8) return '#10b981'; // Near target - Green
    return '#3b82f6'; // Under - Blue
  };

  const macroData = [
    { name: 'Protein', current: current.protein, target: targets.protein, color: '#3b82f6' },
    { name: 'Carbs', current: current.carbs, target: targets.carbs, color: '#f59e0b' },
    { name: 'Fat', current: current.fat, target: targets.fat, color: '#8b5cf6' },
  ];

  const calorieRatio = Math.min((current.calories / targets.calories) * 100, 100);

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-lg font-bold text-slate-800">Daily Allowance</h3>
        <span className="text-xs font-semibold px-2 py-1 bg-slate-100 rounded-full text-slate-500 uppercase">Live Tracking</span>
      </div>

      <div className="mb-8">
        <div className="flex justify-between text-sm mb-2">
          <span className="font-medium">Total Calories</span>
          <span className="font-bold">{Math.round(current.calories)} / {targets.calories} kcal</span>
        </div>
        <div className="h-4 w-full bg-slate-100 rounded-full overflow-hidden">
          <div 
            className="h-full bg-emerald-500 transition-all duration-500" 
            style={{ width: `${calorieRatio}%` }}
          />
        </div>
      </div>

      <div className="grid grid-cols-3 gap-4">
        {macroData.map((macro) => (
          <div key={macro.name} className="flex flex-col items-center">
            <div className="relative w-16 h-16 sm:w-20 sm:h-20">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={[
                      { value: Math.min(macro.current, macro.target) },
                      { value: Math.max(0, macro.target - macro.current) }
                    ]}
                    innerRadius="70%"
                    outerRadius="100%"
                    paddingAngle={0}
                    dataKey="value"
                    startAngle={90}
                    endAngle={-270}
                  >
                    <Cell fill={macro.color} />
                    <Cell fill="#f1f5f9" />
                  </Pie>
                </PieChart>
              </ResponsiveContainer>
              <div className="absolute inset-0 flex flex-center items-center justify-center">
                <span className="text-[10px] sm:text-xs font-bold">{Math.round((macro.current / macro.target) * 100)}%</span>
              </div>
            </div>
            <span className="mt-2 text-xs font-semibold text-slate-600">{macro.name}</span>
            <span className="text-[10px] text-slate-400">{Math.round(macro.current)}g</span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MacroTracker;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import Header from './components/Header';
import MacroTracker from './components/MacroTracker';
import DetectionOverlay from './components/DetectionOverlay';
import { analyzeFoodImage } from './geminiService';
import { FoodItem, UserProfile, DetectionResult, NutritionData } from './types';

// Utility to convert File to Base64
const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = error => reject(error);
  });
};

const App: React.FC = () => {
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [detectionResults, setDetectionResults] = useState<DetectionResult | null>(null);
  const [imageDims, setImageDims] = useState({ width: 0, height: 0 });
  const [userProfile, setUserProfile] = useState<UserProfile>({
    name: "Alex",
    dailyTargets: {
      calories: 2200,
      protein: 160,
      carbs: 250,
      fat: 70,
      fiber: 30
    }
  });

  // Track macros for the "current session" (simulated daily history)
  const [consumedToday, setConsumedToday] = useState<NutritionData>({
    calories: 840,
    protein: 45,
    carbs: 110,
    fat: 22,
    fiber: 12
  });

  const imageRef = useRef<HTMLImageElement>(null);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Reset UI
    setDetectionResults(null);
    const previewUrl = URL.createObjectURL(file);
    setImagePreview(previewUrl);

    // Prepare for analysis
    setIsAnalyzing(true);
    try {
      const base64 = await fileToBase64(file);
      const result = await analyzeFoodImage(base64);
      setDetectionResults(result);

      // Update totals (Add up all detected items)
      const sessionTotals = result.items.reduce((acc, item) => {
        const factor = item.estimatedWeightGrams / 100;
        return {
          calories: acc.calories + (item.nutritionPer100g.calories * factor),
          protein: acc.protein + (item.nutritionPer100g.protein * factor),
          carbs: acc.carbs + (item.nutritionPer100g.carbs * factor),
          fat: acc.fat + (item.nutritionPer100g.fat * factor),
          fiber: acc.fiber + (item.nutritionPer100g.fiber * factor),
        };
      }, { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0 });

      setConsumedToday(prev => ({
        calories: prev.calories + sessionTotals.calories,
        protein: prev.protein + sessionTotals.protein,
        carbs: prev.carbs + sessionTotals.carbs,
        fat: prev.fat + sessionTotals.fat,
        fiber: prev.fiber + sessionTotals.fiber,
      }));

    } catch (error) {
      console.error("Analysis Error:", error);
      alert("Failed to analyze image. Check your API key or connection.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const updateImageDims = () => {
    if (imageRef.current) {
      setImageDims({
        width: imageRef.current.clientWidth,
        height: imageRef.current.clientHeight
      });
    }
  };

  useEffect(() => {
    window.addEventListener('resize', updateImageDims);
    return () => window.removeEventListener('resize', updateImageDims);
  }, []);

  return (
    <div className="min-h-screen pb-20">
      <Header />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Left Column: Input & Preview */}
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
              <div className="p-6">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="text-xl font-bold text-slate-800">Analyze Plate</h2>
                  <label className="cursor-pointer bg-emerald-50 text-emerald-600 px-4 py-2 rounded-lg text-sm font-semibold hover:bg-emerald-100 transition-colors">
                    Upload Photo
                    <input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} />
                  </label>
                </div>

                <div className="relative bg-slate-100 rounded-xl min-h-[300px] flex items-center justify-center overflow-hidden">
                  {imagePreview ? (
                    <>
                      <img 
                        ref={imageRef}
                        src={imagePreview} 
                        className="w-full h-auto object-contain max-h-[600px]"
                        onLoad={updateImageDims}
                        alt="Uploaded food"
                      />
                      {detectionResults && (
                        <DetectionOverlay 
                          items={detectionResults.items} 
                          imageWidth={imageDims.width}
                          imageHeight={imageDims.height}
                        />
                      )}
                      {isAnalyzing && (
                        <div className="absolute inset-0 bg-white/60 backdrop-blur-sm flex flex-col items-center justify-center">
                          <div className="w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                          <p className="text-emerald-700 font-medium animate-pulse">Running AI Vision Analysis...</p>
                        </div>
                      )}
                    </>
                  ) : (
                    <div className="text-center p-12">
                      <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm text-slate-400">
                        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                      </div>
                      <p className="text-slate-500 font-medium">Upload a photo of your meal to start</p>
                      <p className="text-slate-400 text-xs mt-1">YOLOv8 + Gemini AI Analysis</p>
                    </div>
                  )}
                </div>
              </div>

              {/* Detected Items List */}
              {detectionResults && (
                <div className="border-t border-slate-100 p-6 bg-slate-50/30">
                  <h3 className="text-sm font-bold text-slate-500 uppercase tracking-wider mb-4">Detected Components</h3>
                  <div className="space-y-3">
                    {detectionResults.items.map((item) => (
                      <div key={item.id} className="bg-white p-4 rounded-xl border border-slate-200 flex flex-wrap items-center justify-between gap-4">
                        <div className="flex items-center space-x-3">
                          <div className="w-10 h-10 bg-emerald-100 rounded-lg flex items-center justify-center text-emerald-600">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                            </svg>
                          </div>
                          <div>
                            <p className="font-bold text-slate-800">{item.name}</p>
                            <p className="text-xs text-slate-400">Est. {item.estimatedWeightGrams}g • {(item.confidence * 100).toFixed(0)}% Match</p>
                          </div>
                        </div>
                        <div className="flex space-x-6">
                           <div className="text-center">
                            <p className="text-[10px] text-slate-400 font-bold uppercase">Prot</p>
                            <p className="text-sm font-semibold text-blue-600">{Math.round(item.nutritionPer100g.protein * (item.estimatedWeightGrams/100))}g</p>
                          </div>
                           <div className="text-center">
                            <p className="text-[10px] text-slate-400 font-bold uppercase">Carb</p>
                            <p className="text-sm font-semibold text-amber-600">{Math.round(item.nutritionPer100g.carbs * (item.estimatedWeightGrams/100))}g</p>
                          </div>
                           <div className="text-center">
                            <p className="text-[10px] text-slate-400 font-bold uppercase">Fat</p>
                            <p className="text-sm font-semibold text-purple-600">{Math.round(item.nutritionPer100g.fat * (item.estimatedWeightGrams/100))}g</p>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Smart Alternatives */}
            {detectionResults && detectionResults.smartAlternatives.length > 0 && (
              <div className="bg-gradient-to-br from-indigo-500 to-indigo-700 p-6 rounded-2xl text-white shadow-lg">
                <div className="flex items-center space-x-2 mb-4">
                  <div className="bg-white/20 p-2 rounded-lg">
                    <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                    </svg>
                  </div>
                  <h3 className="text-lg font-bold">Smart Alternatives</h3>
                </div>
                <p className="text-indigo-100 text-sm mb-6">Based on your macros, try these next time to hit your targets faster:</p>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  {detectionResults.smartAlternatives.map((alt, idx) => (
                    <div key={idx} className="bg-white/10 backdrop-blur-md rounded-xl p-4 border border-white/20">
                      <p className="font-bold text-white mb-1">{alt.name}</p>
                      <p className="text-xs text-indigo-100 mb-3 leading-relaxed">{alt.reason}</p>
                      <div className="flex gap-2">
                        {alt.estimatedMacros?.protein && (
                           <span className="text-[10px] bg-white/20 px-1.5 py-0.5 rounded">P: {alt.estimatedMacros.protein}g</span>
                        )}
                        {alt.estimatedMacros?.calories && (
                           <span className="text-[10px] bg-white/20 px-1.5 py-0.5 rounded">C: {alt.estimatedMacros.calories}</span>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Right Column: Tracker & Recommendations */}
          <div className="space-y-6">
            <MacroTracker current={consumedToday} targets={userProfile.dailyTargets} />

            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
              <h3 className="text-lg font-bold text-slate-800 mb-4">Traffic-Light Verdict</h3>
              <div className="space-y-4">
                <RecommendationRow 
                  label="Protein Intake" 
                  value={consumedToday.protein} 
                  target={userProfile.dailyTargets.protein} 
                  unit="g" 
                />
                <RecommendationRow 
                  label="Fat Saturation" 
                  value={consumedToday.fat} 
                  target={userProfile.dailyTargets.fat} 
                  unit="g" 
                />
                <RecommendationRow 
                  label="Fiber Intake" 
                  value={consumedToday.fiber} 
                  target={userProfile.dailyTargets.fiber} 
                  unit="g" 
                  inverse
                />
              </div>
            </div>

            <div className="bg-slate-900 p-6 rounded-2xl text-white">
              <h4 className="font-bold mb-2">Pro Tip</h4>
              <p className="text-sm text-slate-400 leading-relaxed">
                Drinking 500ml of water before this meal can boost metabolic rate by up to 30% for about an hour.
              </p>
              <button className="mt-4 w-full py-2 bg-emerald-500 hover:bg-emerald-600 rounded-lg text-sm font-bold transition-colors">
                Log Water Intake
              </button>
            </div>
          </div>

        </div>
      </main>

      {/* Mobile Sticky CTA */}
      <div className="fixed bottom-6 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] max-w-md lg:hidden z-50">
        <label className="flex items-center justify-center space-x-3 bg-emerald-500 hover:bg-emerald-600 text-white py-4 rounded-2xl shadow-xl cursor-pointer transition-transform active:scale-95">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" />
          </svg>
          <span className="font-bold text-lg">Scan Meal</span>
          <input type="file" className="hidden" accept="image/*" capture="environment" onChange={handleImageUpload} />
        </label>
      </div>
    </div>
  );
};

interface RecRowProps {
  label: string;
  value: number;
  target: number;
  unit: string;
  inverse?: boolean;
}

const RecommendationRow: React.FC<RecRowProps> = ({ label, value, target, unit, inverse = false }) => {
  const ratio = value / target;
  let status: '✅' | '⚠️' | '❌' = '✅';
  let message = "";

  if (inverse) {
    if (ratio >= 0.8) { status = '✅'; message = "Excellent"; }
    else if (ratio >= 0.5) { status = '⚠️'; message = "Boost intake"; }
    else { status = '❌'; message = "Critical low"; }
  } else {
    if (ratio <= 0.9) { status = '✅'; message = "On track"; }
    else if (ratio <= 1.1) { status = '⚠️'; message = "Approaching limit"; }
    else { status = '❌'; message = "Over target"; }
  }

  return (
    <div className="flex items-center justify-between p-3 rounded-xl bg-slate-50 border border-slate-100">
      <div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-tighter">{label}</p>
        <p className="text-sm font-semibold text-slate-700">{message}</p>
      </div>
      <div className="flex items-center space-x-3">
        <span className="text-lg">{status}</span>
        <div className="text-right">
          <p className="text-sm font-bold text-slate-800">{Math.round(value)}{unit}</p>
          <p className="text-[10px] text-slate-400">of {target}{unit}</p>
        </div>
      </div>
    </div>
  );
};

export default App;

export interface BoundingBox {
  ymin: number;
  xmin: number;
  ymax: number;
  xmax: number;
}

export interface NutritionData {
  calories: number;
  protein: number;
  carbs: number;
  fat: number;
  fiber: number;
}

export interface FoodItem {
  id: string;
  name: string;
  confidence: number;
  box: BoundingBox;
  nutritionPer100g: NutritionData;
  estimatedWeightGrams: number;
}

export interface UserProfile {
  id: string;
  email: string;
  name: string;
  dailyTargets: NutritionData;
}

export interface DetectionResult {
  items: FoodItem[];
  smartAlternatives: {
    name: string;
    reason: string;
