import Auth from './components/Auth';
import ProfileSettings from './components/ProfileSettings';
import { analyzeFoodImage } from './geminiService';
import { FoodItem, UserProfile, DetectionResult, NutritionData, HistoryItem } from './types';

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = reject;
  });
};

const App: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [detectionResults, setDetectionResults] = useState<DetectionResult | null>(null);
  const [imageDims, setImageDims] = useState({ width: 0, height: 0 });
  const imageRef = useRef<HTMLImageElement>(null);

  // Persistence
  useEffect(() => {
    const savedUser = localStorage.getItem('nutrivision_user');
    const savedHistory = localStorage.getItem('nutrivision_history');
    if (savedUser) setUser(JSON.parse(savedUser));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
  }, []);

  useEffect(() => {
    if (user) localStorage.setItem('nutrivision_user', JSON.stringify(user));
  }, [user]);

  useEffect(() => {
    localStorage.setItem('nutrivision_history', JSON.stringify(history));
  }, [history]);

  const consumedToday = useMemo(() => {
    const today = new Date().setHours(0, 0, 0, 0);
    return history
      .filter(item => new Date(item.timestamp).setHours(0, 0, 0, 0) === today)
      .reduce((acc, entry) => ({
        calories: acc.calories + entry.totalMacros.calories,
        protein: acc.protein + entry.totalMacros.protein,
        carbs: acc.carbs + entry.totalMacros.carbs,
        fat: acc.fat + entry.totalMacros.fat,
        fiber: acc.fiber + entry.totalMacros.fiber,
      }), { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0 });
  }, [history]);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!user) return;
    const file = e.target.files?.[0];
    if (!file) return;

    const previewUrl = URL.createObjectURL(file);
    setImagePreview(previewUrl);
    setDetectionResults(null);
    setIsAnalyzing(true);

    try {
      const base64 = await fileToBase64(file);
      const result = await analyzeFoodImage(base64, user.dailyTargets);
      setDetectionResults(result);

      const totalMacros = result.items.reduce((acc, item) => {
        const f = item.estimatedWeightGrams / 100;
        return {
          calories: acc.calories + (item.nutritionPer100g.calories * f),
          protein: acc.protein + (item.nutritionPer100g.protein * f),
          carbs: acc.carbs + (item.nutritionPer100g.carbs * f),
          fat: acc.fat + (item.nutritionPer100g.fat * f),
          fiber: acc.fiber + (item.nutritionPer100g.fiber * f),
        };
      }, { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0 });

      const newEntry: HistoryItem = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: Date.now(),
        image: previewUrl,
        items: result.items,
        totalMacros
      };

      setHistory(prev => [newEntry, ...prev]);
    } catch (error) {
      console.error(error);
      alert("Analysis failed. Please try again.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const deleteHistoryItem = (id: string) => {
    setHistory(prev => prev.filter(item => item.id !== id));
  };

  const updateImageDims = () => {
    if (imageRef.current) {
      setImageDims({ width: imageRef.current.clientWidth, height: imageRef.current.clientHeight });
    }
  };

  if (!user) return <Auth onLogin={u => { setUser(u); localStorage.setItem('nutrivision_user', JSON.stringify(u)); }} />;

  return (
    <div className="min-h-screen pb-24 bg-slate-50">
      <Header />
      {isSettingsOpen && <ProfileSettings profile={user} onUpdate={setUser} onClose={() => setIsSettingsOpen(false)} />}

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-6">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-slate-900">Health Dashboard</h2>
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="p-2 bg-white rounded-xl shadow-sm border border-slate-200 hover:border-emerald-500 transition-colors"
          >
            <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
          </button>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white rounded-3xl shadow-sm border border-slate-200 p-6">
              <div className="flex items-center justify-between mb-4">
                <h3 className="font-bold text-lg">Scan Nutrition</h3>
                <label className="flex items-center space-x-2 bg-emerald-500 hover:bg-emerald-600 text-white px-4 py-2 rounded-xl text-sm font-bold transition-all shadow-md shadow-emerald-100 cursor-pointer">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                  <span>Upload</span>
                  <input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} />
                </label>
              </div>

              <div className="relative aspect-video bg-slate-100 rounded-2xl flex items-center justify-center overflow-hidden border-2 border-dashed border-slate-200">
                {imagePreview ? (
                  <>
                    <img ref={imageRef} src={imagePreview} className="max-h-full w-auto object-contain" onLoad={updateImageDims} />
                    {detectionResults && <DetectionOverlay items={detectionResults.items} imageWidth={imageDims.width} imageHeight={imageDims.height} />}
                    {isAnalyzing && (
                      <div className="absolute inset-0 bg-white/80 backdrop-blur-sm flex flex-col items-center justify-center">
                        <div className="w-10 h-10 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                        <p className="mt-4 font-bold text-emerald-800 animate-pulse">Scanning Portions...</p>
                      </div>
                    )}
