                ) : (
                  <div className="text-center p-8 text-slate-400">
                    <svg className="w-12 h-12 mx-auto mb-3 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
                    <p className="font-medium">No meal scanned yet</p>
                  </div>
                )}
              </div>
            </div>

            {detectionResults && (
              <div className="bg-gradient-to-br from-indigo-600 to-violet-700 rounded-3xl p-6 text-white shadow-xl shadow-indigo-100 animate-slide-in-up">
                <div className="flex items-center space-x-3 mb-4">
                  <div className="p-2 bg-white/20 rounded-lg">🚀</div>
                  <h4 className="text-lg font-bold">Smart Swap Recommendations</h4>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  {detectionResults.smartAlternatives.map((alt, i) => (
                    <div key={i} className="bg-white/10 backdrop-blur-lg border border-white/20 p-4 rounded-2xl hover:bg-white/20 transition-all">
                      <p className="font-bold text-sm mb-1">{alt.name}</p>
                      <p className="text-[11px] text-indigo-100 leading-relaxed mb-3">{alt.reason}</p>
                      <div className="flex items-center justify-between">
                         <span className="text-[10px] bg-emerald-400/30 text-emerald-100 px-2 py-0.5 rounded-full font-bold">Recommended</span>
                         <span className="text-[10px] font-mono">{alt.estimatedMacros?.calories} kcal</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="space-y-4">
              <h3 className="font-bold text-slate-800 px-1">Today's Timeline</h3>
              {history.length === 0 ? (
                <div className="bg-white rounded-2xl border border-slate-100 p-12 text-center text-slate-400">
                  <p>Your history will appear here once you scan a meal.</p>
