const RecommendationRow: React.FC<{ label: string; value: number; target: number; unit: string; inverse?: boolean }> = ({ label, value, target, unit, inverse }) => {
  const ratio = value / target;
  let status = ratio > 1 ? (inverse ? '✅' : '❌') : (ratio > 0.8 ? '✅' : '⚠️');
  if (inverse && ratio < 0.5) status = '❌';

  return (
    <div className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 border border-slate-100">
      <div>
        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{label}</p>
        <div className="flex items-center space-x-2">
          <span className="text-sm font-bold text-slate-800">{Math.round(value)}{unit}</span>
          <span className="text-[10px] text-slate-400">/ {target}{unit}</span>
        </div>
      </div>
      <span className="text-xl">{status}</span>
    </div>
  );
};

