import React, { useState } from 'react';
import { UserProfile } from '../types';

interface AuthProps {
  onLogin: (user: UserProfile) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (isLogin) {
      // Check credentials in localStorage
      const savedUserStr = localStorage.getItem(`auth_user_${email}`);
      if (!savedUserStr) {
        setError('No account found with this email.');
        return;
      }

      const savedUser = JSON.parse(savedUserStr);
      if (savedUser.password !== password) {
        setError('Incorrect password. Please try again.');
        return;
      }

      onLogin({
        id: savedUser.id,
        email: savedUser.email,
        name: savedUser.name,
        dailyTargets: savedUser.dailyTargets || {
          calories: 2200,
          protein: 160,
          carbs: 250,
          fat: 70,
          fiber: 30
        }
      });
    } else {
      // Registration
      const existing = localStorage.getItem(`auth_user_${email}`);
      if (existing) {
        setError('Email already registered.');
        return;
      }

      const newUser = {
        id: Math.random().toString(36).substr(2, 9),
        email,
        password,
        name,
        dailyTargets: {
          calories: 2200,
          protein: 160,
          carbs: 250,
          fat: 70,
          fiber: 30
        }
      };

      localStorage.setItem(`auth_user_${email}`, JSON.stringify(newUser));
      onLogin({
        id: newUser.id,
        email: newUser.email,
        name: newUser.name,
        dailyTargets: newUser.dailyTargets
      });
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 px-4">
      <div className="max-w-md w-full bg-white rounded-[2rem] shadow-2xl p-10 border border-slate-200">
        <div className="text-center mb-10">
          <div className="inline-flex bg-emerald-100 p-4 rounded-3xl text-emerald-600 mb-6 shadow-sm">
            <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          </div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">NUTRI<span className="text-emerald-500">VISION</span></h2>
          <p className="text-slate-400 font-medium mt-2">{isLogin ? 'Welcome back, athlete!' : 'Begin your fitness journey'}</p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-2xl flex items-center space-x-3 text-red-600 text-sm font-medium animate-pulse">
            <svg className="w-5 h-5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
            </svg>
            <span>{error}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          {!isLogin && (
            <div className="space-y-1">
              <label className="text-xs font-bold text-slate-400 uppercase ml-1">Full Name</label>
              <input
                required
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full px-5 py-3 rounded-2xl bg-slate-50 border border-slate-200 focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all font-medium"
                placeholder="Alex Thompson"
              />
            </div>
          )}
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-400 uppercase ml-1">Email</label>
            <input
              required
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-5 py-3 rounded-2xl bg-slate-50 border border-slate-200 focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all font-medium"
              placeholder="alex@example.com"
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-400 uppercase ml-1">Password</label>
            <input
              required
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-5 py-3 rounded-2xl bg-slate-50 border border-slate-200 focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all font-medium"
              placeholder="••••••••"
            />
          </div>

          <button
            type="submit"
            className="w-full py-4 bg-slate-900 hover:bg-slate-800 text-white rounded-2xl font-bold shadow-xl shadow-slate-200 transition-all active:scale-[0.98] mt-4"
          >
            {isLogin ? 'Sign In' : 'Register Account'}
          </button>
        </form>

        <div className="mt-8 text-center">
          <button
            onClick={() => { setIsLogin(!isLogin); setError(''); }}
            className="text-sm font-bold text-emerald-600 hover:text-emerald-700 transition-colors"
          >
            {isLogin ? "New here? Create an account" : "Already have an account? Login"}
          </button>
        </div>
      </div>
    </div>
  );
};

