import React, { useState, useRef, useEffect, useMemo } from 'react';
import Header from './components/Header';
import MacroTracker from './components/MacroTracker';
import DetectionOverlay from './components/DetectionOverlay';
import Auth from './components/Auth';
import ProfileSettings from './components/ProfileSettings';
import { analyzeFoodImage } from './geminiService';
import { FoodItem, UserProfile, DetectionResult, NutritionData, HistoryItem } from './types';

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = reject;
  });
};

const App: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [detectionResults, setDetectionResults] = useState<DetectionResult | null>(null);
  const [imageDims, setImageDims] = useState({ width: 0, height: 0 });
  const [waterTotal, setWaterTotal] = useState(0);
  const imageRef = useRef<HTMLImageElement>(null);

  // Persistence
  useEffect(() => {
    const savedUser = localStorage.getItem('nutrivision_user');
    const savedHistory = localStorage.getItem('nutrivision_history');
    const savedWater = localStorage.getItem('nutrivision_water');
    if (savedUser) setUser(JSON.parse(savedUser));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedWater) setWaterTotal(parseInt(savedWater));
  }, []);

  useEffect(() => {
    if (user) {
      localStorage.setItem('nutrivision_user', JSON.stringify(user));
      // Also update the auth record so passwords stay in sync with profile updates if any
      const authKey = `auth_user_${user.email}`;
      const existingAuth = localStorage.getItem(authKey);
      if (existingAuth) {
        const authData = JSON.parse(existingAuth);
        localStorage.setItem(authKey, JSON.stringify({ ...authData, dailyTargets: user.dailyTargets, name: user.name }));
      }
    }
  }, [user]);

  useEffect(() => {
    localStorage.setItem('nutrivision_history', JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    localStorage.setItem('nutrivision_water', waterTotal.toString());
  }, [waterTotal]);

  const consumedToday = useMemo(() => {
    const today = new Date().setHours(0, 0, 0, 0);
    return history
      .filter(item => new Date(item.timestamp).setHours(0, 0, 0, 0) === today)
      .reduce((acc, entry) => ({
        calories: acc.calories + entry.totalMacros.calories,
        protein: acc.protein + entry.totalMacros.protein,
        carbs: acc.carbs + entry.totalMacros.carbs,
        fat: acc.fat + entry.totalMacros.fat,
        fiber: acc.fiber + entry.totalMacros.fiber,
      }), { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0 });
  }, [history]);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!user) return;
    const file = e.target.files?.[0];
    if (!file) return;

    const previewUrl = URL.createObjectURL(file);
    setImagePreview(previewUrl);
    setDetectionResults(null);
    setIsAnalyzing(true);

    try {
      const base64 = await fileToBase64(file);
      const result = await analyzeFoodImage(base64, user.dailyTargets);
      setDetectionResults(result);

      const totalMacros = result.items.reduce((acc, item) => {
        const f = item.estimatedWeightGrams / 100;
        return {
          calories: acc.calories + (item.nutritionPer100g.calories * f),
          protein: acc.protein + (item.nutritionPer100g.protein * f),
          carbs: acc.carbs + (item.nutritionPer100g.carbs * f),
          fat: acc.fat + (item.nutritionPer100g.fat * f),
          fiber: acc.fiber + (item.nutritionPer100g.fiber * f),
        };
      }, { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0 });

      const newEntry: HistoryItem = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: Date.now(),
        image: previewUrl,
        items: result.items,
        totalMacros
      };

      setHistory(prev => [newEntry, ...prev]);
    } catch (error) {
      console.error(error);
      alert("AI analysis encountered an error. Please try again.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const deleteHistoryItem = (id: string) => {
    setHistory(prev => prev.filter(item => item.id !== id));
  };

  const updateImageDims = () => {
    if (imageRef.current) {
      setImageDims({ width: imageRef.current.clientWidth, height: imageRef.current.clientHeight });
    }
  };

  const logWater = (amount: number) => {
    setWaterTotal(prev => prev + amount);
  };

  if (!user) return <Auth onLogin={setUser} />;

  return (
    <div className="min-h-screen pb-24 bg-slate-50 text-slate-900">
