      {isSettingsOpen && <ProfileSettings profile={user} onUpdate={setUser} onClose={() => setIsSettingsOpen(false)} />}

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        <div className="flex flex-col md:flex-row md:items-end justify-between mb-8 gap-4">
          <div>
            <h2 className="text-3xl font-black tracking-tight">Health Dashboard</h2>
            <p className="text-slate-400 font-medium">Tracking {user.name}'s daily performance</p>
          </div>
          <div className="flex items-center space-x-3">
             <button 
              onClick={() => setIsSettingsOpen(true)}
              className="flex items-center space-x-2 px-5 py-2.5 bg-white border border-slate-200 rounded-2xl shadow-sm font-bold text-sm hover:border-emerald-500 transition-all"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              <span>Settings</span>
            </button>
            <button 
              onClick={() => { setUser(null); localStorage.removeItem('nutrivision_user'); }}
              className="p-2.5 bg-white border border-slate-200 rounded-2xl shadow-sm text-red-500 hover:bg-red-50 transition-colors"
              title="Logout"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-8">
            <div className="bg-white rounded-[2rem] shadow-sm border border-slate-200 p-8">
              <div className="flex items-center justify-between mb-6">
                <h3 className="font-bold text-xl">Analyze Meal</h3>
                <label className="flex items-center space-x-2 bg-emerald-500 hover:bg-emerald-600 text-white px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-lg shadow-emerald-100 cursor-pointer active:scale-95">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                  <span>Upload Image</span>
                  <input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} />
                </label>
              </div>

              <div className="relative aspect-video bg-slate-50 rounded-[1.5rem] flex items-center justify-center overflow-hidden border-2 border-dashed border-slate-200 group">
                {imagePreview ? (
                  <>
                    <img ref={imageRef} src={imagePreview} className="max-h-full w-auto object-contain transition-transform duration-500" onLoad={updateImageDims} />
                    {detectionResults && <DetectionOverlay items={detectionResults.items} imageWidth={imageDims.width} imageHeight={imageDims.height} />}
                    {isAnalyzing && (
                      <div className="absolute inset-0 bg-white/80 backdrop-blur-md flex flex-col items-center justify-center animate-fade-in">
                        <div className="w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                        <p className="mt-5 font-black text-emerald-800 animate-pulse tracking-tight">AI PORTION ANALYSIS...</p>
