};

const RecommendationRow: React.FC<{ label: string; value: number; target: number; unit: string; inverse?: boolean }> = ({ label, value, target, unit, inverse }) => {
  const ratio = value / target;
  let statusIcon = '✅';
  let statusColor = 'text-emerald-500';

  if (inverse) {
    if (ratio < 0.5) { statusIcon = '❌'; statusColor = 'text-red-500'; }
    else if (ratio < 0.8) { statusIcon = '⚠️'; statusColor = 'text-amber-500'; }
  } else {
    if (ratio > 1.1) { statusIcon = '❌'; statusColor = 'text-red-500'; }
    else if (ratio > 0.9) { statusIcon = '⚠️'; statusColor = 'text-amber-500'; }
  }

  return (
    <div className="flex items-center justify-between p-4 rounded-3xl bg-slate-50 border border-slate-100 transition-all hover:bg-white hover:border-slate-200">
      <div>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{label}</p>
        <div className="flex items-center space-x-2">
          <span className="text-sm font-black text-slate-900">{Math.round(value)}{unit}</span>
          <span className="text-[10px] text-slate-400 font-bold">/ {target}{unit}</span>
        </div>
      </div>
      <div className={`text-xl ${statusColor}`}>{statusIcon}</div>
    </div>
  );
};

