import React, { useState, useRef, useEffect, useMemo } from 'react';
import confetti from 'canvas-confetti';
import Header from './components/Header';
import MacroTracker from './components/MacroTracker';
import DetectionOverlay from './components/DetectionOverlay';
import Auth from './components/Auth';
import ProfileSettings from './components/ProfileSettings';
import DashboardAnalytics from './components/DashboardAnalytics';
import ManualEntryModal from './components/ManualEntryModal';
import { analyzeFoodImage } from './geminiService';
import { FoodItem, UserProfile, DetectionResult, NutritionData, HistoryItem } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isManualModalOpen, setIsManualModalOpen] = useState(false);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [detectionResults, setDetectionResults] = useState<DetectionResult | null>(null);
  const [imageDims, setImageDims] = useState({ width: 0, height: 0 });
  const [waterTotal, setWaterTotal] = useState(0);

  // Search and Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterRange, setFilterRange] = useState<'today' | '7days' | 'all'>('all');

  const imageRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    const savedUser = localStorage.getItem('nutrivision_user');
    const savedHistory = localStorage.getItem('nutrivision_history');
    const savedWater = localStorage.getItem('nutrivision_water');
    if (savedUser) setUser(JSON.parse(savedUser));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedWater) setWaterTotal(parseInt(savedWater));
  }, []);

  useEffect(() => {
    if (user) localStorage.setItem('nutrivision_user', JSON.stringify(user));
  }, [user]);

  useEffect(() => {
    localStorage.setItem('nutrivision_history', JSON.stringify(history));
  }, [history]);

  const consumedToday = useMemo(() => {
    const today = new Date().setHours(0, 0, 0, 0);
    return history
      .filter(item => new Date(item.timestamp).setHours(0, 0, 0, 0) === today)
      .reduce((acc, entry) => ({
        calories: acc.calories + entry.totalMacros.calories,
        protein: acc.protein + entry.totalMacros.protein,
        carbs: acc.carbs + entry.totalMacros.carbs,
        fat: acc.fat + entry.totalMacros.fat,
        fiber: acc.fiber + entry.totalMacros.fiber,
      }), { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0 });
  }, [history]);

  // Celebratory effect when protein goal hit
  useEffect(() => {
    if (user && consumedToday.protein >= user.dailyTargets.protein && consumedToday.protein < user.dailyTargets.protein + 10) {
      confetti({ particleCount: 150, spread: 70, origin: { y: 0.6 }, colors: ['#10b981', '#34d399'] });
    }
  }, [consumedToday.protein, user]);

  const filteredHistory = useMemo(() => {
    return history.filter(item => {
      const nameMatch = item.items.some(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()));
      const now = Date.now();
      const itemTime = item.timestamp;
      let dateMatch = true;

      if (filterRange === 'today') {
        dateMatch = new Date(itemTime).toDateString() === new Date().toDateString();
      } else if (filterRange === '7days') {
        dateMatch = (now - itemTime) <= 7 * 24 * 60 * 60 * 1000;
      }

      return nameMatch && dateMatch;
    });
  }, [history, searchTerm, filterRange]);

  const handleManualAdd = (macros: NutritionData, name: string) => {
    const newEntry: HistoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      image: '', 
      items: [{ id: 'manual', name, confidence: 1, box: {ymin:0,xmin:0,ymax:0,xmax:0}, nutritionPer100g: macros, estimatedWeightGrams: 100 }],
      totalMacros: macros
    };
    setHistory(prev => [newEntry, ...prev]);
    setIsManualModalOpen(false);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!user) return;
    const file = e.target.files?.[0];
    if (!file) return;

    const previewUrl = URL.createObjectURL(file);
    setImagePreview(previewUrl);
    setDetectionResults(null);
    setIsAnalyzing(true);

    try {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const result = await analyzeFoodImage(base64, user.dailyTargets);
        setDetectionResults(result);

        const totalMacros = result.items.reduce((acc, item) => {
          const f = item.estimatedWeightGrams / 100;
          return {
            calories: acc.calories + (item.nutritionPer100g.calories * f),
            protein: acc.protein + (item.nutritionPer100g.protein * f),
            carbs: acc.carbs + (item.nutritionPer100g.carbs * f),
            fat: acc.fat + (item.nutritionPer100g.fat * f),
            fiber: acc.fiber + (item.nutritionPer100g.fiber * f),
          };
        }, { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0 });

        setHistory(prev => [{ id: Math.random().toString(36).substr(2, 9), timestamp: Date.now(), image: previewUrl, items: result.items, totalMacros }, ...prev]);
        setIsAnalyzing(false);
      };
    } catch (error) {
      alert("Analysis failed.");
      setIsAnalyzing(false);
    }
  };

  if (!user) return <Auth onLogin={setUser} />;

  return (
    <div className="min-h-screen pb-24 bg-slate-50 text-slate-900">
      <Header />
      {isSettingsOpen && <ProfileSettings profile={user} onUpdate={setUser} onClose={() => setIsSettingsOpen(false)} />}
      {isManualModalOpen && <ManualEntryModal userTargets={user.dailyTargets} onAdd={handleManualAdd} onClose={() => setIsManualModalOpen(false)} />}

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8 space-y-10">

        {/* Analytics Section */}
        <section className="space-y-4">
          <h3 className="text-xl font-black text-slate-900 tracking-tight px-1">Performance Insight</h3>
          <DashboardAnalytics history={history} targets={user.dailyTargets} current={consumedToday} />
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-8">
            <div className="bg-white rounded-[2rem] shadow-sm border border-slate-200 p-8">
              <div className="flex items-center justify-between mb-6">
                <h3 className="font-black text-xl">Analyze Meal</h3>
                <div className="flex gap-2">
                  <button 
                    onClick={() => setIsManualModalOpen(true)}
                    className="flex items-center space-x-2 bg-slate-100 hover:bg-slate-200 text-slate-700 px-5 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all"
                  >
                    <span>Manual Log</span>
                  </button>
                  <label className="flex items-center space-x-2 bg-emerald-500 hover:bg-emerald-600 text-white px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-lg shadow-emerald-100 cursor-pointer active:scale-95">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                    <span>Scan Plate</span>
                    <input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} />
                  </label>
                </div>
              </div>

              <div className="relative aspect-video bg-slate-50 rounded-[1.5rem] flex items-center justify-center overflow-hidden border-2 border-dashed border-slate-200 group">
                {imagePreview ? (
                  <>
                    <img ref={imageRef} src={imagePreview} className="max-h-full w-auto object-contain" onLoad={() => setImageDims({width: imageRef.current?.clientWidth||0, height: imageRef.current?.clientHeight||0})} />
