                    <button key={amt} onClick={() => setWaterTotal(v => v + amt)} className="py-3 bg-white/5 hover:bg-emerald-500 rounded-2xl text-[10px] font-black tracking-widest transition-all">+{amt}ML</button>
                  ))}
                </div>
                <button onClick={() => setWaterTotal(0)} className="w-full mt-4 py-2 text-[10px] font-bold text-slate-500 hover:text-white transition-all uppercase tracking-widest">Reset Today</button>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

const VerdictRow: React.FC<{ label: string; value: number; target: number; unit: string; inverse?: boolean }> = ({ label, value, target, unit, inverse }) => {
  const ratio = value / target;
  let statusColor = ratio >= 1 ? 'text-emerald-500' : (ratio > 0.8 ? 'text-amber-500' : 'text-slate-400');
  if (inverse && ratio < 0.5) statusColor = 'text-red-500';

  return (
    <div className="flex items-center justify-between p-4 bg-slate-50 rounded-[1.5rem] border border-slate-100">
      <div>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{label}</p>
        <div className="flex items-center space-x-2">
          <span className="text-sm font-black text-slate-900">{Math.round(value)}{unit}</span>
          <span className="text-[10px] text-slate-400 font-bold">/ {target}{unit}</span>
        </div>
      </div>
      <div className={`text-xl font-bold ${statusColor}`}>
        {ratio >= 1 ? '✅' : (ratio > 0.8 ? '⚠️' : '🎯')}
      </div>
    </div>
  );
};

