import { GoogleGenAI, Type } from "@google/genai";
import { DetectionResult, NutritionData, ReverseSearchResult } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export async function analyzeFoodImage(base64Image: string, targets: NutritionData): Promise<DetectionResult> {
  const modelName = "gemini-3-flash-preview";
  const prompt = `
    Analyze this food image for the 'Nutri-Smart' project.
    1. Detect food items with bounding boxes [ymin, xmin, ymax, xmax] (0-1000).
    2. Provide nutrition per 100g and estimated total weight.
    3. Suggest healthier cooking methods (e.g., grilling vs frying) for each item as 'cookingMethodAdvice'.
    4. Suggest 3 healthier alternatives based on these user targets:
       Calories: ${targets.calories}, Protein: ${targets.protein}g, Carbs: ${targets.carbs}g, Fat: ${targets.fat}g.
  `;

  const response = await ai.models.generateContent({
    model: modelName,
    contents: [{ parts: [{ inlineData: { mimeType: "image/jpeg", data: base64Image } }, { text: prompt }] }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          items: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                name: { type: Type.STRING },
                confidence: { type: Type.NUMBER },
                box: {
                  type: Type.OBJECT,
                  properties: { ymin: { type: Type.NUMBER }, xmin: { type: Type.NUMBER }, ymax: { type: Type.NUMBER }, xmax: { type: Type.NUMBER } },
                },
                nutritionPer100g: {
                  type: Type.OBJECT,
                  properties: { calories: { type: Type.NUMBER }, protein: { type: Type.NUMBER }, carbs: { type: Type.NUMBER }, fat: { type: Type.NUMBER }, fiber: { type: Type.NUMBER } },
                },
                estimatedWeightGrams: { type: Type.NUMBER },
                cookingMethodAdvice: { type: Type.STRING }
              },
              required: ["id", "name", "nutritionPer100g", "estimatedWeightGrams"]
            }
          },
          smartAlternatives: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                reason: { type: Type.STRING },
                estimatedMacros: { type: Type.OBJECT, properties: { calories: { type: Type.NUMBER }, protein: { type: Type.NUMBER }, carbs: { type: Type.NUMBER }, fat: { type: Type.NUMBER } } }
              },
            }
          }
        }
      }
    }
  });
  return JSON.parse(response.text);
}

export async function reverseNutritionSearch(inputMacros: Partial<NutritionData>): Promise<ReverseSearchResult[]> {
  const modelName = "gemini-3-flash-preview";
  const prompt = `
    Reverse Nutrition Search for Nutri-Smart.
    The user wants a meal with approximately:
    Calories: ${inputMacros.calories}, Protein: ${inputMacros.protein}g, Carbs: ${inputMacros.carbs}g.

    Suggest 3 unique meal options that precisely match or optimize for these values.
    Include ingredients and professional cooking tips to minimize fat/maximize nutrition.
  `;

  const response = await ai.models.generateContent({
    model: modelName,
    contents: [{ text: prompt }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            mealName: { type: Type.STRING },
            ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
            macros: {
              type: Type.OBJECT,
              properties: { calories: { type: Type.NUMBER }, protein: { type: Type.NUMBER }, carbs: { type: Type.NUMBER }, fat: { type: Type.NUMBER }, fiber: { type: Type.NUMBER } }
            },
            cookingTips: { type: Type.STRING }
          }
        }
      }
    }
  });
  return JSON.parse(response.text);
}

