export async function getRecommendationsForMacros(macros: NutritionData, targets: NutritionData): Promise<{ alternatives: { name: string, reason: string }[] }> {
  const modelName = "gemini-3-flash-preview";
  const prompt = `
    Based on the current meal macros:
    Calories: ${macros.calories}, Protein: ${macros.protein}g, Carbs: ${macros.carbs}g, Fat: ${macros.fat}g, Fiber: ${macros.fiber}g.

    And the user's daily targets:
    Calories: ${targets.calories}, Protein: ${targets.protein}g, Carbs: ${targets.carbs}g, Fat: ${targets.fat}g, Fiber: ${targets.fiber}g.

    Suggest 3 healthier meal alternatives or "smart swaps" that would help the user stay within their targets.
  `;

  const response = await ai.models.generateContent({
    model: modelName,
    contents: [{ text: prompt }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          alternatives: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                reason: { type: Type.STRING }
              },
              required: ["name", "reason"]
            }
