export async function reverseNutritionSearch(inputMacros: Partial<NutritionData>): Promise<ReverseSearchResult[]> {
  const modelName = "gemini-3-flash-preview";
  const prompt = `
    Reverse Nutrition Search for Nutri-Smart.
    The user wants a meal with approximately:
    Calories: ${inputMacros.calories}, Protein: ${inputMacros.protein}g, Carbs: ${inputMacros.carbs}g.

    Suggest 3 unique meal options that precisely match or optimize for these values.
    Include ingredients and professional cooking tips to minimize fat/maximize nutrition.
  `;

  const response = await ai.models.generateContent({
    model: modelName,
    contents: [{ text: prompt }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            mealName: { type: Type.STRING },
            ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
            macros: {
              type: Type.OBJECT,
              properties: { calories: { type: Type.NUMBER }, protein: { type: Type.NUMBER }, carbs: { type: Type.NUMBER }, fat: { type: Type.NUMBER }, fiber: { type: Type.NUMBER } }
            },
            cookingTips: { type: Type.STRING }
          }
        }
      }
    }
  });
  return JSON.parse(response.text);
}

