      if (!savedUserStr) {
        setError('No account found with this email.');
        return;
      }

      const savedUser = JSON.parse(savedUserStr);
      if (savedUser.password !== password) {
        setError('Incorrect password. Please try again.');
        return;
      }

      onLogin({
        id: savedUser.id,
        email: savedUser.email,
        name: savedUser.name,
