  const [isAbstractOpen, setIsAbstractOpen] = useState(false);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [detectionResults, setDetectionResults] = useState<DetectionResult | null>(null);
  const [imageDims, setImageDims] = useState({ width: 0, height: 0 });
  const [waterTotal, setWaterTotal] = useState(0);
  const [customWater, setCustomWater] = useState('');

  // Search and Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterRange, setFilterRange] = useState<'today' | '7days' | 'all'>('all');

  const imageRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    const savedUser = localStorage.getItem('nutrivision_user');
    const savedHistory = localStorage.getItem('nutrivision_history');
    const savedWater = localStorage.getItem('nutrivision_water');
    if (savedUser) setUser(JSON.parse(savedUser));
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedWater) setWaterTotal(parseInt(savedWater));
  }, []);

  useEffect(() => {
    if (user) localStorage.setItem('nutrivision_user', JSON.stringify(user));
  }, [user]);

  useEffect(() => {
    localStorage.setItem('nutrivision_history', JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    localStorage.setItem('nutrivision_water', waterTotal.toString());
  }, [waterTotal]);

  const consumedToday = useMemo(() => {
    const today = new Date().setHours(0, 0, 0, 0);
    return history
      .filter(item => new Date(item.timestamp).setHours(0, 0, 0, 0) === today)
      .reduce((acc, entry) => ({
        calories: acc.calories + entry.totalMacros.calories,
        protein: acc.protein + entry.totalMacros.protein,
        carbs: acc.carbs + entry.totalMacros.carbs,
        fat: acc.fat + entry.totalMacros.fat,
        fiber: acc.fiber + entry.totalMacros.fiber,
      }), { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0 });
  }, [history]);

  const filteredHistory = useMemo(() => {
    return history.filter(item => {
      const nameMatch = item.items.some(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()));
      const now = Date.now();
      const itemTime = item.timestamp;
      let dateMatch = true;

      if (filterRange === 'today') {
        dateMatch = new Date(itemTime).toDateString() === new Date().toDateString();
      } else if (filterRange === '7days') {
        dateMatch = (now - itemTime) <= 7 * 24 * 60 * 60 * 1000;
      }

      return nameMatch && dateMatch;
    });
  }, [history, searchTerm, filterRange]);

  const handleManualAdd = (macros: NutritionData, name: string) => {
    const newEntry: HistoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      image: '', 
      items: [{ id: 'manual', name, confidence: 1, box: {ymin:0,xmin:0,ymax:0,xmax:0}, nutritionPer100g: macros, estimatedWeightGrams: 100 }],
      totalMacros: macros
    };
    setHistory(prev => [newEntry, ...prev]);
    setIsManualModalOpen(false);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!user) return;
    const file = e.target.files?.[0];
    if (!file) return;

    const previewUrl = URL.createObjectURL(file);
    setImagePreview(previewUrl);
    setDetectionResults(null);
    setIsAnalyzing(true);

    try {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const result = await analyzeFoodImage(base64, user.dailyTargets);
        setDetectionResults(result);

