import React, { useState } from 'react';
import { UserProfile } from '../types';

interface AuthProps {
  onLogin: (user: UserProfile) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Normalize email and trim inputs
    const cleanEmail = email.toLowerCase().trim();
    const cleanPassword = password.trim();
    const storageKey = `nutrismart_account_${cleanEmail}`;

    if (isLogin) {
      // Login Logic
      const savedUserStr = localStorage.getItem(storageKey);

      if (!savedUserStr) {
        setError('No account found with this email. Please register first.');
        return;
      }

      try {
        const savedUser = JSON.parse(savedUserStr);
        // Direct comparison of trimmed passwords
        if (savedUser.password === cleanPassword) {
          const userProfile: UserProfile = {
            id: savedUser.id,
            email: savedUser.email,
            name: savedUser.name,
            dailyTargets: savedUser.dailyTargets || {
              calories: 2200,
              protein: 160,
              carbs: 250,
              fat: 70,
              fiber: 30
            }
          };
          // Save session
          localStorage.setItem('nutrismart_session', JSON.stringify(userProfile));
          onLogin(userProfile);
        } else {
          setError('Incorrect password. Please check your credentials.');
        }
      } catch (err) {
        setError('Account data corrupted. Please register again.');
      }
    } else {
      // Registration Logic
      const existing = localStorage.getItem(storageKey);
      if (existing) {
        setError('This email is already registered. Please sign in.');
        return;
      }

      const newUser = {
        id: Math.random().toString(36).substr(2, 9),
        email: cleanEmail,
        password: cleanPassword, // Storing clean password
        name: name.trim(),
        dailyTargets: {
          calories: 2200,
          protein: 160,
          carbs: 250,
          fat: 70,
          fiber: 30
        }
      };

      // Store in permanent "database"
      localStorage.setItem(storageKey, JSON.stringify(newUser));

      const userProfile: UserProfile = {
        id: newUser.id,
        email: newUser.email,
        name: newUser.name,
        dailyTargets: newUser.dailyTargets
      };

      // Set session and login
      localStorage.setItem('nutrismart_session', JSON.stringify(userProfile));
      onLogin(userProfile);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 px-4">
      <div className="max-w-md w-full bg-white rounded-[2rem] shadow-2xl p-10 border border-slate-200">
        <div className="text-center mb-10">
          <div className="inline-flex bg-white rounded-3xl overflow-hidden mb-6 shadow-xl border-4 border-emerald-50 w-24 h-24">
            <img 
              src="https://images.unsplash.com/photo-1512621776951-a57141f2eefd?q=80&w=200&auto=format&fit=crop" 
              alt="NutriSmart Welcome" 
              className="w-full h-full object-cover"
            />
          </div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">NUTRI<span className="text-emerald-500">SMART</span></h2>
          <p className="text-slate-400 font-medium mt-2">
            {isLogin ? 'Welcome back, health champion!' : 'Create your NutriSmart account'}
          </p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-2xl flex items-center space-x-3 text-red-600 text-sm font-medium animate-fade-in">
            <svg className="w-5 h-5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
            </svg>
            <span>{error}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          {!isLogin && (
            <div className="space-y-1">
              <label className="text-xs font-bold text-slate-400 uppercase ml-1">Full Name</label>
              <input
                required
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full px-5 py-3 rounded-2xl bg-slate-50 border border-slate-200 focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all font-medium"
                placeholder="Alex Thompson"
              />
            </div>
          )}
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-400 uppercase ml-1">Email</label>
            <input
              required
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-5 py-3 rounded-2xl bg-slate-50 border border-slate-200 focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all font-medium"
              placeholder="alex@example.com"
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-400 uppercase ml-1">Password</label>
            <input
              required
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-5 py-3 rounded-2xl bg-slate-50 border border-slate-200 focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all font-medium"
              placeholder="••••••••"
            />
          </div>

          <button
            type="submit"
            className="w-full py-4 bg-slate-900 hover:bg-slate-800 text-white rounded-2xl font-bold shadow-xl shadow-slate-200 transition-all active:scale-[0.98] mt-4"
          >
            {isLogin ? 'Sign In' : 'Register Account'}
          </button>
        </form>

        <div className="mt-8 text-center">
          <button
            onClick={() => { setIsLogin(!isLogin); setError(''); }}
            className="text-sm font-bold text-emerald-600 hover:text-emerald-700 transition-colors"
          >
            {isLogin ? "New here? Create an account" : "Already have an account? Login"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import confetti from 'canvas-confetti';
import Header from './components/Header';
import MacroTracker from './components/MacroTracker';
import DetectionOverlay from './components/DetectionOverlay';
import Auth from './components/Auth';
import ProfileSettings from './components/ProfileSettings';
import DashboardAnalytics from './components/DashboardAnalytics';
import ManualEntryModal from './components/ManualEntryModal';
import ReverseSearchModal from './components/ReverseSearchModal';
import AbstractModal from './components/AbstractModal';
import { analyzeFoodImage } from './geminiService';
import { FoodItem, UserProfile, DetectionResult, NutritionData, HistoryItem } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isManualModalOpen, setIsManualModalOpen] = useState(false);
  const [isReverseSearchOpen, setIsReverseSearchOpen] = useState(false);
  const [isAbstractOpen, setIsAbstractOpen] = useState(false);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [detectionResults, setDetectionResults] = useState<DetectionResult | null>(null);
  const [imageDims, setImageDims] = useState({ width: 0, height: 0 });
  const [waterTotal, setWaterTotal] = useState(0);
  const [customWater, setCustomWater] = useState('');

  // Search and Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterRange, setFilterRange] = useState<'today' | '7days' | 'all'>('all');

  const imageRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    // Session restoration
    const savedSession = localStorage.getItem('nutrismart_session');
    const savedHistory = localStorage.getItem('nutrismart_history');
    const savedWater = localStorage.getItem('nutrismart_water');

    if (savedSession) {
      try {
        setUser(JSON.parse(savedSession));
      } catch (e) {
        localStorage.removeItem('nutrismart_session');
      }
    }

    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedWater) setWaterTotal(parseInt(savedWater) || 0);
  }, []);

  useEffect(() => {
    if (user) {
      localStorage.setItem('nutrismart_session', JSON.stringify(user));
      // Also update the permanent account storage if user edited their profile
      localStorage.setItem(`nutrismart_account_${user.email}`, JSON.stringify(user));
    } else {
      localStorage.removeItem('nutrismart_session');
    }
  }, [user]);

  useEffect(() => {
    localStorage.setItem('nutrismart_history', JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    localStorage.setItem('nutrismart_water', waterTotal.toString());
  }, [waterTotal]);

  const consumedToday = useMemo(() => {
    const today = new Date().setHours(0, 0, 0, 0);
    return history
      .filter(item => new Date(item.timestamp).setHours(0, 0, 0, 0) === today)
      .reduce((acc, entry) => ({
        calories: acc.calories + entry.totalMacros.calories,
        protein: acc.protein + entry.totalMacros.protein,
        carbs: acc.carbs + entry.totalMacros.carbs,
        fat: acc.fat + entry.totalMacros.fat,
        fiber: acc.fiber + entry.totalMacros.fiber,
      }), { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0 });
  }, [history]);

  const filteredHistory = useMemo(() => {
    return history.filter(item => {
      const nameMatch = item.items.some(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()));
      const now = Date.now();
      const itemTime = item.timestamp;
      let dateMatch = true;

      if (filterRange === 'today') {
        dateMatch = new Date(itemTime).toDateString() === new Date().toDateString();
      } else if (filterRange === '7days') {
        dateMatch = (now - itemTime) <= 7 * 24 * 60 * 60 * 1000;
      }

      return nameMatch && dateMatch;
    });
  }, [history, searchTerm, filterRange]);

  const handleManualAdd = (macros: NutritionData, name: string) => {
    const newEntry: HistoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      image: '', 
      items: [{ id: 'manual', name, confidence: 1, box: {ymin:0,xmin:0,ymax:0,xmax:0}, nutritionPer100g: macros, estimatedWeightGrams: 100 }],
      totalMacros: macros
    };
    setHistory(prev => [newEntry, ...prev]);
    setIsManualModalOpen(false);
    confetti({ particleCount: 100, spread: 70, origin: { y: 0.6 } });
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!user) return;
    const file = e.target.files?.[0];
    if (!file) return;

    const previewUrl = URL.createObjectURL(file);
    setImagePreview(previewUrl);
    setDetectionResults(null);
    setIsAnalyzing(true);

    try {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const result = await analyzeFoodImage(base64, user.dailyTargets);
        setDetectionResults(result);

        const totalMacros = result.items.reduce((acc, item) => {
          const f = item.estimatedWeightGrams / 100;
          return {
            calories: acc.calories + (item.nutritionPer100g.calories * f),
            protein: acc.protein + (item.nutritionPer100g.protein * f),
            carbs: acc.carbs + (item.nutritionPer100g.carbs * f),
            fat: acc.fat + (item.nutritionPer100g.fat * f),
            fiber: acc.fiber + (item.nutritionPer100g.fiber * f),
          };
        }, { calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0 });

        setHistory(prev => [{ id: Math.random().toString(36).substr(2, 9), timestamp: Date.now(), image: previewUrl, items: result.items, totalMacros }, ...prev]);
        setIsAnalyzing(false);
        confetti({ particleCount: 150, spread: 100, origin: { y: 0.7 } });
      };
    } catch (error) {
      alert("AI Intelligence failed. Re-connecting...");
      setIsAnalyzing(false);
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('nutrismart_session');
  };

  if (!user) return <Auth onLogin={setUser} />;

  return (
    <div className="min-h-screen pb-24 bg-slate-50 text-slate-900">
      <Header />
      {isSettingsOpen && (
        <ProfileSettings 
          profile={user} 
          onUpdate={setUser} 
          onLogout={handleLogout}
          onResetData={() => { setHistory([]); setWaterTotal(0); }}
          onClose={() => setIsSettingsOpen(false)} 
        />
      )}
      {isManualModalOpen && <ManualEntryModal userTargets={user.dailyTargets} onAdd={handleManualAdd} onClose={() => setIsManualModalOpen(false)} />}
      {isReverseSearchOpen && <ReverseSearchModal onClose={() => setIsReverseSearchOpen(false)} />}
      {isAbstractOpen && <AbstractModal onClose={() => setIsAbstractOpen(false)} />}

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8 space-y-10">

        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
             <div className="w-16 h-16 bg-white rounded-3xl flex items-center justify-center shadow-2xl shadow-emerald-200 overflow-hidden border-4 border-white">
               <img 
                 src="https://images.unsplash.com/photo-1490645935967-10de6ba17061?q=80&w=150&auto=format&fit=crop" 
                 alt="NutriSmart AI" 
                 className="w-full h-full object-cover"
               />
             </div>
             <div>
               <h2 className="text-4xl font-black tracking-tighter">NutriSmart AI</h2>
               <button onClick={() => setIsAbstractOpen(true)} className="text-[10px] font-black uppercase text-indigo-600 tracking-widest hover:underline flex items-center gap-1 mt-1">
                  View Project Abstract <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 5l7 7-7 7" strokeWidth={3} /></svg>
               </button>
             </div>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <button 
              onClick={() => setIsReverseSearchOpen(true)}
              className="px-6 py-3 bg-indigo-600 text-white rounded-2xl shadow-xl shadow-indigo-100 font-black text-xs uppercase tracking-widest transition-all active:scale-95 border-b-4 border-indigo-800"
            >
              Reverse Search
            </button>
